from pathlib import Path
import shutil, re

SRC=Path('outputs/mq/review/md')
REF=Path('متن ها/mq/md')
FINAL=Path('final/mq')
REPORT=Path('reports/mq_finalization.md')
FINAL.mkdir(parents=True,exist_ok=True)

for n in range(1,9):
    shutil.copyfile(SRC/f'{n}.md', FINAL/f'episode-{n:02d}.md')

applied=[]
def edit(n, old, new, label):
    p=FINAL/f'episode-{n:02d}.md'
    s=p.read_text(encoding='utf-8')
    count=s.count(old)
    if count != 1:
        raise SystemExit(f'anchor {n} {label!r} count={count}')
    p.write_text(s.replace(old,new,1),encoding='utf-8')
    applied.append((n,label))

