for n in range(1,9):
    p=FINAL/f'episode-{n:02d}.md'
    s=p.read_text(encoding='utf-8')
    for bad in BAD:
        if bad in s:
            raise SystemExit(f'bad marker {bad!r} in {p}')

# ensure source files remain untouched by this script (only reads/copies)
